source_json:
"namespace N { namespace { using T = int; }
constexpr int T = 3;
auto f(){ return sizeof(T); } }
"

"constexpr int width = 4;
namespace A { constexpr int width = 2; using T = int[width]; }
namespace B { using T = int[width]; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"int values[] = {1, 2, 3, 4};
constexpr auto n = sizeof(values);
namespace A { using T = int[n]; }
namespace B { using T = int[12]; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"struct C { int field; int method(); };
namespace A { using T = int[sizeof(&C::field)]; }
namespace B { using T = int[sizeof(&C::method)]; }
namespace Both { using namespace A; using namespace B; }
void consume(Both::T);
"

"template<class T> struct Box {};
namespace A { using T = Box<int>; }
namespace B { using T = Box<long>; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"template<auto N> struct Number {};
namespace A { using T = Number<4>; }
namespace B { using T = Number<4u>; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"namespace first { inline int value; }
namespace second { inline int value; }
template<int *P> struct Ref {};
namespace A { using T = Ref<&first::value>; }
namespace B { using T = Ref<&second::value>; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"struct Data { int first, second; };
template<int Data::*M> struct Field {};
namespace A { using T = Field<&Data::first>; }
namespace B { using T = Field<&Data::second>; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"namespace first { int apply(int); }
namespace second { int apply(int); }
template<int (*F)(int)> struct Handler {};
namespace A { using T = Handler<first::apply>; }
namespace B { using T = Handler<&second::apply>; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"template<class T, class U> int visit(T *, U);
template<class T, class U> int visit(T, U *);
template<int (*F)(int *, int *)> struct Handler {};
namespace A { using T = Handler<visit>; }
namespace B { using T = Handler<&visit<int,int *>>; }
namespace C { using namespace A; using namespace B; }
void consume(C::T);
"

"auto generic = [](auto x){return x;};
auto plain = [](int x){return x;};
decltype(generic) select(double) { return generic; }
decltype(plain) select(int) { return plain; }
int use(){return select(1).operator()<int>(4);}
"

"template<class A, class B> struct Pick;
template<class T, class U> struct Pick<T *, U> { using Id = int; };
template<class T, class U> struct Pick<T, U *> { static constexpr int Id = 1; };
int f() { return sizeof(Pick<int *,int *>::Id); }
"

"auto generic = [](auto x){return x;};
auto plain = [](int x){return x;};
template<class T> decltype(plain)& choose(T){return plain;}
template<class T> requires (sizeof(T) > 1)
decltype(generic)& choose(T){return generic;}
int f(){return choose('a').operator()<int>(3);}
"
